# Build normalized shapes on lower 1 mask; placement options fixed orientation
pieces=[]
for p in comps:
 minr=min(r for r,c in p); minc=min(c for r,c in p)
 shape=tuple(sorted((r-minr,c-minc,grid[r][c]) for r,c in p))
 pieces.append(shape)
mask={(r,c) for r in range(8) for c in range(20) if grid[r+12][c]==1}
# enumerate placements
placements=[]
for i,shape in enumerate(pieces):
 h=max(r for r,c,v in shape)+1; w=max(c for r,c,v in shape)+1
 arr=[]
 for r0 in range(8-h+1):
  for c0 in range(20-w+1):
   cells={(r0+r,c0+c) for r,c,v in shape}
   if cells<=mask: arr.append((i,r0,c0,cells))
 placements.extend(arr)
by_piece={i:[p for p in placements if p[0]==i] for i in range(len(pieces))}
by_cell={c:[] for c in mask}
for p in placements:
 for c in p[3]: by_cell[c].append(p)
[(i,len(shape),len(by_piece[i])) for i,shape in enumerate(pieces)],len(mask),len(placements)
